cd /workspace/dataset; perl -e '
my @alpha = ("a","b","_","X","Y","9"," ","-",".","/",":","\t","\xc3","\xa9","+","A","z");
srand(7);
sub camel { my $s=shift; my $o=""; my $cap=0;
  for my $c (split //,$s) {
    if ($c eq "_") { $cap=1 }
    elsif ($cap) { $o .= ($c =~ /[a-z]/ ? uc($c) : $c); $cap=0 }
    else { $o .= $c }
  } return $o; }
my $bad=0; my $n=0;
for my $t (1..400) {
  my $len = 1+int(rand(12));
  my $w = join("", map { $alpha[int(rand(scalar @alpha))] } 1..$len);
  next if $w =~ /\n/;
  open(my $fh, "-|", "./test15_executable", "dummy", $w) or die;
  local $/; my $out = <$fh>; close $fh;
  my @lines = split /\n/, $out, -1;
  my $got = $lines[3];
  my $exp = camel($w);
  $n++;
  if ($got ne $exp) { $bad++; printf("MISMATCH w=%s got=%s exp=%s\n", unpack("H*",$w), unpack("H*",$got), unpack("H*",$exp)); }
}
print "tested=$n bad=$bad\n";'

