// inflection::Inflector::camelize(const std::string& input) -> std::string
// Pure byte-level transform. Stateless (no dependence on Inflector::initialize()
// tables, no memoization, no dependence on other args). Never throws, never
// truncates, no length limit. Operates on raw bytes of std::string.
//
// The ONLY separator byte is '_' (0x5F). No other byte (including '-', ' ',
// '.', '/', ':', ';', ',', '\t', '\n', '\r', '\v', '\f', digits, 0x7F,
// and every byte 0x80..0xFF) is a separator or is otherwise special.
// Uppercasing is ASCII-only ("C" locale std::toupper): exactly 'a'..'z'
// (0x61..0x7A) map to 'A'..'Z' (0x41..0x5A); every other byte is emitted
// unchanged.
// The capitalize flag is cleared by ANY non-'_' byte, even one that cannot be
// uppercased ("a_-b" -> "a-b", NOT "a-B").
// The first byte of the result is NEVER forced to upper or lower case unless it
// was preceded by at least one '_' in the input.

function camelize(input):
    out = ""                       // empty std::string
    cap = false
    for each byte c in input:      // left to right, no lookahead
        if c == 0x5F ('_'):
            cap = true             // separator is consumed, never emitted
        else if cap:
            if 0x61 <= c <= 0x7A:  // 'a'..'z'
                out += (c - 0x20)  // ASCII uppercase
            else:
                out += c           // unchanged (digits, symbols, 'A'-'Z',
                                   //  control bytes, 0x80..0xFF)
            cap = false
        else:
            out += c
    return out
    // note: a trailing run of '_' leaves cap == true at end-of-string and
    // contributes nothing to the output; an all-'_' input returns "".

// Equivalent formulation (behaviorally indistinguishable in every probe):
//   split input on '_' into tokens (keeping empty tokens);
//   result = token[0] + concat over i>=1 of ascii_upcase_first_byte(token[i])
//   where ascii_upcase_first_byte("") == "".
